SELECT

FROM generated_report
WHERE id = #{id}
  AND user_id = #{userId}
LIMIT 1

SELECT

FROM generated_report
WHERE verification_id = #{verificationId}
  AND user_id = #{userId}
ORDER BY id DESC
LIMIT 1

